-- Philippine compliance preparation: effective rules, tax snapshots, and immutable accountant packs.
create function private.compliance_module_enabled(requested_organization_id uuid)returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.organization_modules module join public.module_definitions definition on definition.id=module.module_id where module.organization_id=requested_organization_id and module.is_enabled and definition.key='compliance');$$;

create table public.tax_rule_sets(
 id uuid primary key default gen_random_uuid(),code text not null,version integer not null check(version>0),name text not null,tax_kind text not null check(tax_kind in('vat','percentage_tax','withholding_expanded','withholding_compensation','exempt','non_vat')),
 transaction_scope text not null check(transaction_scope in('sale','purchase','expense','payroll','all')),rate numeric(9,6) not null check(rate between 0 and 100),effective_from date not null,effective_to date,
 source_agency text not null,source_reference text not null,legally_reviewed boolean not null default false,configuration jsonb not null default'{}'check(jsonb_typeof(configuration)='object'),created_at timestamptz not null default now(),
 unique(code,version),check(effective_to is null or effective_to>=effective_from)
);
insert into public.tax_rule_sets(code,version,name,tax_kind,transaction_scope,rate,effective_from,source_agency,source_reference,legally_reviewed)values
 ('VAT-12',1,'Standard output/input VAT','vat','all',12,date'2024-01-01','BIR','EOPT / RR 7-2024 review baseline',false),
 ('NON-VAT',1,'Non-VAT sale','non_vat','sale',0,date'2024-01-01','BIR','EOPT invoicing review baseline',false),
 ('VAT-EXEMPT',1,'VAT-exempt transaction','exempt','all',0,date'2024-01-01','BIR','Business classification required',false),
 ('PERCENTAGE-3',1,'Percentage tax preparation category','percentage_tax','sale',3,date'2024-01-01','BIR','Rate requires accountant review',false)
on conflict(code,version)do nothing;

create table public.business_tax_profiles(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete cascade,effective_from date not null,effective_to date,
 taxpayer_type text not null check(taxpayer_type in('sole_proprietor','partnership','corporation','cooperative','professional','other')),
 registration_type text not null check(registration_type in('vat','non_vat_percentage','non_vat_exempt')),percentage_tax_rate numeric(9,6)check(percentage_tax_rate between 0 and 100),tin text not null,rdo_code text,branch_code text,registered_name text not null,registered_address text not null,
 registration_references jsonb not null default'{}'check(jsonb_typeof(registration_references)='object'),fiscal_year_start_month integer not null check(fiscal_year_start_month between 1 and 12),accountant_name text,accountant_email text,
 created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(id,organization_id),check(effective_to is null or effective_to>=effective_from)
);
create unique index business_tax_profile_current_idx on public.business_tax_profiles(organization_id)where effective_to is null;
create table public.transaction_tax_snapshots(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete cascade,source_type text not null,source_id uuid not null,source_line_id uuid not null,
 rule_set_id uuid not null references public.tax_rule_sets(id)on delete restrict,tax_category_code text not null,tax_rule_version integer not null,taxable_base numeric(18,4)not null,tax_amount numeric(18,4)not null,exemption_reason text,
 snapshot jsonb not null default'{}'check(jsonb_typeof(snapshot)='object'),created_at timestamptz not null default now(),unique(organization_id,source_type,source_line_id)
);
create table public.compliance_periods(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete cascade,period_type text not null check(period_type in('monthly','quarterly','annual')),starts_on date not null,ends_on date not null,due_on date,
 status text not null default'open'check(status in('open','review','ready','amended')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(id,organization_id),unique(organization_id,period_type,starts_on),check(ends_on>=starts_on)
);
create table public.compliance_exceptions(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null,period_id uuid not null,exception_code text not null,severity text not null check(severity in('warning','blocking')),message text not null,source_type text,source_id uuid,status text not null default'open'check(status in('open','resolved','accepted')),resolution text,resolved_at timestamptz,resolved_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(period_id,exception_code,source_type,source_id),foreign key(period_id,organization_id)references public.compliance_periods(id,organization_id)on delete cascade
);
create table public.compliance_packs(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null,period_id uuid not null,version integer not null default 1,status text not null default'draft'check(status in('draft','finalized','superseded')),
 payload jsonb not null check(jsonb_typeof(payload)='object'),control_totals jsonb not null check(jsonb_typeof(control_totals)='object'),checksum text not null,review_message text not null default'Your records are ready for accountant review.',
 created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),finalized_at timestamptz,finalized_by uuid references auth.users(id),unique(id,organization_id),unique(period_id,version),foreign key(period_id,organization_id)references public.compliance_periods(id,organization_id)on delete restrict
);
create index tax_profiles_effective_idx on public.business_tax_profiles(organization_id,effective_from desc);create index tax_snapshots_period_idx on public.transaction_tax_snapshots(organization_id,created_at,source_type);create index compliance_period_status_idx on public.compliance_periods(organization_id,status,ends_on);create index compliance_exceptions_open_idx on public.compliance_exceptions(organization_id,period_id)where status='open';
create trigger set_updated_at before update on public.compliance_periods for each row execute function private.set_updated_at();

create function private.snapshot_transaction_tax()returns trigger language plpgsql security definer set search_path='' as $$declare rule_row public.tax_rule_sets%rowtype;source_type_value text;source_id_value uuid;base_value numeric;tax_value numeric;org uuid;line_id uuid;begin
 if tg_table_name='sales_lines'then source_type_value:='sale';source_id_value:=new.sale_id;base_value:=new.subtotal-new.discount_amount;tax_value:=new.tax_amount;org:=new.organization_id;line_id:=new.id;
 elsif tg_table_name='invoice_lines'then source_type_value:='invoice';source_id_value:=new.invoice_id;base_value:=new.subtotal-new.discount_amount;tax_value:=new.tax_amount;org:=new.organization_id;line_id:=new.id;
 elsif tg_table_name='purchase_order_lines'then source_type_value:='purchase_order';source_id_value:=new.purchase_order_id;base_value:=new.subtotal;tax_value:=new.tax_amount;org:=new.organization_id;line_id:=new.id;
 else return new;end if;
 select*into rule_row from public.tax_rule_sets where code=case when tax_value>0 then'VAT-12'else'NON-VAT'end and effective_from<=current_date and(effective_to is null or effective_to>=current_date)order by version desc limit 1;
 insert into public.transaction_tax_snapshots(organization_id,source_type,source_id,source_line_id,rule_set_id,tax_category_code,tax_rule_version,taxable_base,tax_amount,snapshot)
 values(org,source_type_value,source_id_value,line_id,rule_row.id,rule_row.code,rule_row.version,base_value,tax_value,jsonb_build_object('rate',rule_row.rate,'sourceAgency',rule_row.source_agency,'sourceReference',rule_row.source_reference))on conflict(organization_id,source_type,source_line_id)do nothing;return new;end;$$;
create trigger snapshot_sales_line_tax after insert on public.sales_lines for each row execute function private.snapshot_transaction_tax();
create trigger snapshot_invoice_line_tax after insert on public.invoice_lines for each row execute function private.snapshot_transaction_tax();
create trigger snapshot_purchase_line_tax after insert on public.purchase_order_lines for each row execute function private.snapshot_transaction_tax();

create function private.reject_finalized_compliance_mutation()returns trigger language plpgsql set search_path='' as $$begin if tg_op='DELETE'or old.status in('finalized','superseded')then raise exception'Finalized compliance packs are immutable.'using errcode='42501';end if;return new;end;$$;create trigger compliance_packs_immutable before update or delete on public.compliance_packs for each row execute function private.reject_finalized_compliance_mutation();

create function public.save_business_tax_profile(requested_organization_id uuid,requested_effective_from date,requested_taxpayer_type text,requested_registration_type text,requested_percentage_rate numeric,requested_tin text,requested_rdo_code text,requested_branch_code text,requested_registered_name text,requested_registered_address text,requested_registration_references jsonb,requested_fiscal_month integer,requested_accountant_name text,requested_accountant_email text)returns uuid language plpgsql security definer set search_path='' as $$
declare actor uuid:=(select auth.uid());target_id uuid;begin if actor is null or not private.compliance_module_enabled(requested_organization_id)or not private.can_business_permission(requested_organization_id,'compliance.manage',null)then raise exception'Permission denied.'using errcode='42501';end if;if requested_taxpayer_type not in('sole_proprietor','partnership','corporation','cooperative','professional','other')or requested_registration_type not in('vat','non_vat_percentage','non_vat_exempt')or char_length(btrim(requested_tin))not between 9 and 40 or char_length(btrim(requested_registered_name))not between 2 and 200 or requested_fiscal_month not between 1 and 12 or jsonb_typeof(requested_registration_references)<>'object'then raise exception'Invalid tax profile.'using errcode='22023';end if;update public.business_tax_profiles set effective_to=requested_effective_from-1 where organization_id=requested_organization_id and effective_to is null and effective_from<requested_effective_from;insert into public.business_tax_profiles(organization_id,effective_from,taxpayer_type,registration_type,percentage_tax_rate,tin,rdo_code,branch_code,registered_name,registered_address,registration_references,fiscal_year_start_month,accountant_name,accountant_email,created_by)values(requested_organization_id,requested_effective_from,requested_taxpayer_type,requested_registration_type,case when requested_registration_type='non_vat_percentage'then requested_percentage_rate end,btrim(requested_tin),nullif(btrim(requested_rdo_code),''),nullif(btrim(requested_branch_code),''),btrim(requested_registered_name),btrim(requested_registered_address),requested_registration_references,requested_fiscal_month,nullif(btrim(requested_accountant_name),''),nullif(lower(btrim(requested_accountant_email)) ,''),actor)returning id into target_id;return target_id;end;$$;

create function public.prepare_compliance_period(requested_organization_id uuid,requested_period_type text,requested_starts_on date,requested_ends_on date,requested_due_on date)returns uuid language plpgsql security definer set search_path='' as $$declare actor uuid:=(select auth.uid());target_id uuid;profile_id uuid;begin if actor is null or not private.compliance_module_enabled(requested_organization_id)or not private.can_business_permission(requested_organization_id,'compliance.manage',null)then raise exception'Permission denied.'using errcode='42501';end if;if requested_period_type not in('monthly','quarterly','annual')or requested_ends_on<requested_starts_on then raise exception'Invalid compliance period.'using errcode='22023';end if;insert into public.compliance_periods(organization_id,period_type,starts_on,ends_on,due_on)values(requested_organization_id,requested_period_type,requested_starts_on,requested_ends_on,requested_due_on)on conflict(organization_id,period_type,starts_on)do update set ends_on=excluded.ends_on,due_on=excluded.due_on returning id into target_id;select id into profile_id from public.business_tax_profiles where organization_id=requested_organization_id and effective_from<=requested_ends_on and(effective_to is null or effective_to>=requested_starts_on)order by effective_from desc limit 1;if profile_id is null then insert into public.compliance_exceptions(organization_id,period_id,exception_code,severity,message,source_type)values(requested_organization_id,target_id,'MISSING_TAX_PROFILE','blocking','A reviewed Business tax profile is required.','business')on conflict do nothing;end if;return target_id;end;$$;

create function public.finalize_compliance_pack(requested_organization_id uuid,requested_period_id uuid)returns uuid language plpgsql security definer set search_path='' as $$
declare actor uuid:=(select auth.uid());period_row public.compliance_periods%rowtype;profile_row public.business_tax_profiles%rowtype;payload_value jsonb;totals jsonb;checksum_value text;target_id uuid;next_version integer;blocking integer;begin if actor is null or not private.compliance_module_enabled(requested_organization_id)or not private.can_business_permission(requested_organization_id,'compliance.manage',null)then raise exception'Permission denied.'using errcode='42501';end if;select*into period_row from public.compliance_periods where id=requested_period_id and organization_id=requested_organization_id for update;if period_row.id is null then raise exception'Compliance period not found.'using errcode='P0001';end if;select*into profile_row from public.business_tax_profiles where organization_id=requested_organization_id and effective_from<=period_row.ends_on and(effective_to is null or effective_to>=period_row.starts_on)order by effective_from desc limit 1;select count(*)into blocking from public.compliance_exceptions where period_id=period_row.id and severity='blocking'and status='open';if profile_row.id is null or blocking>0 then raise exception'Compliance pack has blocking exceptions.'using errcode='P0001';end if;
 with sales as(select coalesce(sum(sale.total),0)gross,coalesce(sum(sale.tax_total),0)output_tax,count(*)documents from public.sales_transactions sale where sale.organization_id=requested_organization_id and sale.status in('completed','partially_returned','returned','refunded')and sale.completed_at::date between period_row.starts_on and period_row.ends_on),manual_invoices as(select coalesce(sum(total),0)gross,coalesce(sum(tax_total),0)output_tax,count(*)documents from public.invoices where organization_id=requested_organization_id and source_type<>'sale'and status in('issued','partially_paid','paid','overdue')and invoice_date between period_row.starts_on and period_row.ends_on),purchases as(select coalesce(sum(total),0)gross,coalesce(sum(tax_total),0)input_tax,count(*)documents from public.supplier_invoices where organization_id=requested_organization_id and status<>'cancelled'and invoice_date between period_row.starts_on and period_row.ends_on),expenses_value as(select coalesce(sum(amount),0)gross,count(*)documents from public.expenses where organization_id=requested_organization_id and approval_status='approved'and expense_date between period_row.starts_on and period_row.ends_on),ledger as(select coalesce(sum(line.debit),0)debit,coalesce(sum(line.credit),0)credit from public.journal_entries entry join public.journal_lines line on line.entry_id=entry.id where entry.organization_id=requested_organization_id and entry.status in('posted','reversed')and entry.entry_date between period_row.starts_on and period_row.ends_on)
 select jsonb_build_object('period',jsonb_build_object('type',period_row.period_type,'startsOn',period_row.starts_on,'endsOn',period_row.ends_on),'taxProfile',jsonb_build_object('registrationType',profile_row.registration_type,'tin',profile_row.tin,'rdoCode',profile_row.rdo_code,'branchCode',profile_row.branch_code),'salesJournal',jsonb_build_object('gross',sales.gross+manual_invoices.gross,'outputTax',sales.output_tax+manual_invoices.output_tax,'documents',sales.documents+manual_invoices.documents),'purchaseJournal',jsonb_build_object('gross',purchases.gross,'inputTax',purchases.input_tax,'documents',purchases.documents),'expenseJournal',jsonb_build_object('gross',expenses_value.gross,'documents',expenses_value.documents),'vatSchedule',jsonb_build_object('outputTax',sales.output_tax+manual_invoices.output_tax,'inputTax',purchases.input_tax,'net',sales.output_tax+manual_invoices.output_tax-purchases.input_tax),'percentageTaxSchedule',jsonb_build_object('taxableBase',case when profile_row.registration_type='non_vat_percentage'then sales.gross+manual_invoices.gross else 0 end,'rate',coalesce(profile_row.percentage_tax_rate,0)),'withholdingSchedules',jsonb_build_object('expanded',jsonb_build_array(),'compensation',jsonb_build_array()),'reconciliations',jsonb_build_object('generalLedger',jsonb_build_object('debit',ledger.debit,'credit',ledger.credit),'accountsReceivable',coalesce((select sum(balance_due)from public.invoices where organization_id=requested_organization_id and balance_due>0),0),'accountsPayable',coalesce((select sum(balance_due)from public.supplier_invoices where organization_id=requested_organization_id and balance_due>0),0),'inventory',coalesce((select sum(quantity*average_unit_cost)from public.stock_balances where organization_id=requested_organization_id),0),'unmatchedBankTransactions',(select count(*)from public.bank_transactions where organization_id=requested_organization_id and status in('unmatched','partially_matched')))) into payload_value from sales,manual_invoices,purchases,expenses_value,ledger;
 totals:=jsonb_build_object('sales',(payload_value#>>'{salesJournal,gross}')::numeric,'purchases',(payload_value#>>'{purchaseJournal,gross}')::numeric,'outputTax',(payload_value#>>'{vatSchedule,outputTax}')::numeric,'inputTax',(payload_value#>>'{vatSchedule,inputTax}')::numeric,'ledgerDebit',(payload_value#>>'{reconciliations,generalLedger,debit}')::numeric,'ledgerCredit',(payload_value#>>'{reconciliations,generalLedger,credit}')::numeric);checksum_value:=encode(extensions.digest(payload_value::text||totals::text,'sha256'),'hex');select coalesce(max(version),0)+1 into next_version from public.compliance_packs where period_id=period_row.id;update public.compliance_packs set status='superseded'where period_id=period_row.id and status='finalized';insert into public.compliance_packs(organization_id,period_id,version,status,payload,control_totals,checksum,created_by,finalized_at,finalized_by)values(requested_organization_id,period_row.id,next_version,'finalized',payload_value,totals,checksum_value,actor,now(),actor)returning id into target_id;update public.compliance_periods set status='ready'where id=period_row.id;return target_id;end;$$;

create function public.compliance_dashboard(requested_organization_id uuid)returns jsonb language plpgsql stable security definer set search_path='' as $$declare result jsonb;begin if(select auth.uid())is null or not private.compliance_module_enabled(requested_organization_id)or not private.can_business_permission(requested_organization_id,'compliance.read',null)then raise exception'Permission denied.'using errcode='42501';end if;select jsonb_build_object('hasTaxProfile',exists(select 1 from public.business_tax_profiles where organization_id=requested_organization_id and effective_to is null),'openPeriods',(select count(*)from public.compliance_periods where organization_id=requested_organization_id and status in('open','review')),'readyPacks',(select count(*)from public.compliance_packs where organization_id=requested_organization_id and status='finalized'),'blockingExceptions',(select count(*)from public.compliance_exceptions where organization_id=requested_organization_id and status='open'and severity='blocking'),'latestPack',(select jsonb_build_object('id',pack.id,'periodId',pack.period_id,'version',pack.version,'checksum',pack.checksum,'message',pack.review_message,'finalizedAt',pack.finalized_at)from public.compliance_packs pack where pack.organization_id=requested_organization_id and pack.status='finalized'order by pack.finalized_at desc limit 1))into result;return result;end;$$;

alter table public.tax_rule_sets enable row level security;alter table public.business_tax_profiles enable row level security;alter table public.transaction_tax_snapshots enable row level security;alter table public.compliance_periods enable row level security;alter table public.compliance_exceptions enable row level security;alter table public.compliance_packs enable row level security;
create policy tax_rules_read on public.tax_rule_sets for select to authenticated using(true);
create policy tax_profiles_read on public.business_tax_profiles for select to authenticated using(private.compliance_module_enabled(organization_id)and private.can_business_permission(organization_id,'compliance.read',null));
create policy tax_snapshots_read on public.transaction_tax_snapshots for select to authenticated using(private.compliance_module_enabled(organization_id)and private.can_business_permission(organization_id,'compliance.read',null));
create policy compliance_periods_read on public.compliance_periods for select to authenticated using(private.compliance_module_enabled(organization_id)and private.can_business_permission(organization_id,'compliance.read',null));
create policy compliance_exceptions_read on public.compliance_exceptions for select to authenticated using(private.compliance_module_enabled(organization_id)and private.can_business_permission(organization_id,'compliance.read',null));
create policy compliance_packs_read on public.compliance_packs for select to authenticated using(private.compliance_module_enabled(organization_id)and private.can_business_permission(organization_id,'compliance.read',null));
revoke all on public.tax_rule_sets,public.business_tax_profiles,public.transaction_tax_snapshots,public.compliance_periods,public.compliance_exceptions,public.compliance_packs from public,anon,authenticated;grant select on public.tax_rule_sets,public.business_tax_profiles,public.transaction_tax_snapshots,public.compliance_periods,public.compliance_exceptions,public.compliance_packs to authenticated;
revoke all on function private.compliance_module_enabled(uuid),private.snapshot_transaction_tax(),private.reject_finalized_compliance_mutation()from public,anon,authenticated;grant execute on function private.compliance_module_enabled(uuid)to authenticated;
revoke all on function public.save_business_tax_profile(uuid,date,text,text,numeric,text,text,text,text,text,jsonb,integer,text,text),public.prepare_compliance_period(uuid,text,date,date,date),public.finalize_compliance_pack(uuid,uuid),public.compliance_dashboard(uuid)from public,anon;grant execute on function public.save_business_tax_profile(uuid,date,text,text,numeric,text,text,text,text,text,jsonb,integer,text,text),public.prepare_compliance_period(uuid,text,date,date,date),public.finalize_compliance_pack(uuid,uuid),public.compliance_dashboard(uuid)to authenticated;
